] {\n  font-size: 0.9rem;\n  color: var(--text-secondary);\n  margin-bottom: 8px;\n  word-break: break-word;\n}\n\n.task-metadata[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  font-size: 0.85rem;\n  flex-wrap: wrap;\n}\n\n.task-date[_ngcontent-%COMP%] {\n  color: var(--text-secondary);\n}\n\n.task-status[_ngcontent-%COMP%] {\n  padding: 2px 8px;\n  border-radius: 4px;\n  font-weight: 500;\n  font-size: 0.8rem;\n}\n\n.status-completed[_ngcontent-%COMP%] {\n  background-color: #dcfce7;\n  color: #16a34a;\n}\n\n.status-pending[_ngcontent-%COMP%] {\n  background-color: #fef3c7;\n  color: #d97706;\n}\n\n\n\n.task-actions[_ngcontent-%COMP%] {\n  display: flex;\n  gap: 8px;\n  flex-shrink: 0;\n}\n\n.btn-action[_ngcontent-%COMP%] {\n  width: 32px;\n  height: 32px;\n  padding: 0;\n  border: 1px solid var(--border-color);\n  border-radius: var(--border-radius);\n  background-color: white;\n  cursor: pointer;\n  transition: var(--transition);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1rem;\n}\n\n.btn-action[_ngcontent-%COMP%]:hover:not(:disabled) {\n  border-color: currently-color;\n  background-color: #f3f4f6;\n  transform: scale(1.1);\n}\n\n.btn-action[_ngcontent-%COMP%]:disabled {\n  cursor: not-allowed;\n  opacity: 0.6;\n}\n\n.btn-complete[_ngcontent-%COMP%] {\n  color: var(--secondary-color);\n}\n\n.btn-complete[_ngcontent-%COMP%]:hover {\n  background-color: #dcfce7;\n  border-color: var(--secondary-color);\n}\n\n.btn-delete[_ngcontent-%COMP%] {\n  color: var(--danger-color);\n}\n\n.btn-delete[_ngcontent-%COMP%]:hover {\n  background-color: #fee2e2;\n  border-color: var(--danger-color);\n}\n\n\n\n\n\n@media (max-width: 768px) {\n  .task-list-container[_ngcontent-%COMP%] {\n    padding: 16px;\n  }\n\n  .header[_ngcontent-%COMP%]   .title[_ngcontent-%COMP%] {\n    font-size: 1.8rem;\n  }\n\n  .stats-container[_ngcontent-%COMP%] {\n    grid-template-columns: repeat(2, 1fr);\n  }\n\n  .filter-tabs[_n