import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { TaskService, ITask, ITaskStatistics, ICreateTaskRequest } from '../../services/task.service';


@Component({
  selector: 'app-task-list',
  standalone: true, // Componente standalone (Angular 17+)
  imports: [CommonModule, FormsModule, ReactiveFormsModule],
  templateUrl: './task-list.component.html',
  styleUrls: ['./task-list.component.css'],
})
export class TaskListComponent implements OnInit, OnDestroy {
  // ==========================================
  // PROPIEDADES DEL ESTADO
  // ==========================================

  /** Array de todas las tareas */
  tasks: ITask[] = [];

  /** Array de tareas filtradas según el filtro activo */
  filteredTasks: ITask[] = [];

  /** Estadísticas de tareas (total, completadas, pendientes, porcentaje) */
  statistics: ITaskStatistics | null = null;

  /** Formulario reactivo para crear tareas */
  taskForm: FormGroup;

  // Estados de carga
  /** Indica si se están cargando las tareas */
  isLoadingTasks = false;

  /** Indica si se está creando una nueva tarea */
  isCreatingTask = false;

  /** ID de la tarea que se está eliminando (para mostrar loading en botón) */
  deletingTaskId: number | null = null;

  /** Filtro activo: 'all', 'pending', 'completed' */
  activeFilter: 'all' | 'pending' | 'completed' = 'all';

  // Manejo de errores
  /** Mensaje de error general */
  errorMessage: string | null = null;

  /** Mensaje de éxito temporal */
  successMessage: string | null = null;

  // Subject para unsubscribe automático
  /** Subject que se completa cuando el componente se destruye */
  private destroy$ = new Subject<void>();

  // ==========================================
  // CONSTRUCTOR E INYECCIÓN DE DEPENDENCIAS
  // ==========================================

  constructor(
    private readonly taskService: TaskService,
    private readonly formBuilder: FormBuilder,
  ) {
    this.taskForm = this.createTaskForm();
  }

  // ==========================================
  // CICLO DE VIDA
  // ==========================================

  /**
   * Initialización del componente
   * 
   * Se ejecuta cuando el componente se crea
   * - Cargar tareas
   * - Cargar estadísticas
   */
  ngOnInit(): void {
    this.loadTasks();
    this.loadStatistics();
  }

  /**
   * Limpieza cuando se destruye el componente
   * 
   * - Completar el Subject para hacer unsubscribe automático
   * - Previene memory leaks
   */
  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  // ==========================================
  // MÉTODOS PÚBLICOS
  // ==========================================

  /**
   * Cargar todas las tareas desde el backend
   * 
   * Procesa según el filtro activo:
   * - 'all': Obtiene todas las tareas
   * - 'pending': Obtiene solo pendientes
   * - 'completed': Obtiene solo completadas
   */
  loadTasks(): void {
    this.isLoadingTasks = true;
    this.errorMessage = null;

    let taskObservable$;

    switch (this.activeFilter) {
      case 'pending':
        taskObservable$ = this.taskService.getPendingTasks();
        break;
      case 'completed':
        taskObservable$ = this.taskService.getCompletedTasks();
        break;
      case 'all':
      default:
        taskObservable$ = this.taskService.getAllTasks();
    }

    taskObservable$
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (tasks: ITask[]) => {
          this.tasks = tasks;
          this.filteredTasks = tasks;
          this.isLoadingTasks = false;
        },
        error: (error: Error) => {
          this.handleError('Error al cargar tareas: ' + error.message);
          this.isLoadingTasks = false;
        },
      });
  }

  /**
   * Cargar estadísticas de tareas
   * 
   * Obtiene el total, completadas, pendientes y porcentaje de completamiento
   */
  loadStatistics(): void {
    this.taskService
      .getTaskStatistics()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (stats: ITaskStatistics) => {
          this.statistics = stats;
        },
        error: (error: Error) => {
          console.error('Error al cargar estadísticas:', error);
        },
      });
  }

  /**
   * Crear una nueva tarea desde el formulario
   * 
   * Validaciones:
   * - Formulario debe ser válido
   * - Título no puede estar vacío
   * 
   * Después de crear:
   * - Limpiar formulario
   * - Recargar tareas
   * - Recargar estadísticas
   * - Mostrar mensaje de éxito
   */
  addTask(): void {
    // Validar que el formulario sea válido
    if (this.taskForm.invalid) {
      this.handleError('Por favor, completa el formulario correctamente');
      return;
    }

    this.isCreatingTask = true;
    this.errorMessage = null;

    // Obtener datos del formulario
    const createTaskRequest: ICreateTaskRequest = {
      title: this.taskForm.get('title')?.value.trim(),
      description: this.taskForm.get('description')?.value?.trim() || undefined,
    };

    // Enviar request al backend
    this.taskService
      .createTask(createTaskRequest)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (newTask: ITask) => {
          // Agregar la nueva tarea a la lista
          this.tasks.unshift(newTask);

          // Recargar según filtro
          this.applyFilter(this.activeFilter);

          // Limpiar formulario
          this.taskForm.reset();

          // Actualizar estadísticas
          this.loadStatistics();

          // Mostrar mensaje de éxito
          this.successMessage = `✓ Tarea "${newTask.title}" creada exitosamente`;
          this.hideSuccessMessageAfterDelay();

          this.isCreatingTask = false;
        },
        error: (error: Error) => {
          this.handleError('Error al crear tarea: ' + error.message);
          this.isCreatingTask = false;
        },
      });
  }

  /**
   * Completar una tarea
   * 
   * @param {ITask} task - Tarea a completar
   */
  completeTask(task: ITask): void {
    this.taskService
      .completeTask(task.id)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (completedTask: ITask) => {
          // Actualizar tarea en la lista
          const index = this.tasks.findIndex((t) => t.id === completedTask.id);
          if (index !== -1) {
            this.tasks[index] = completedTask;
          }

          // Recargar filtro
          this.applyFilter(this.activeFilter);

          // Actualizar estadísticas
          this.loadStatistics();

          // Mostrar mensaje de éxito
          this.successMessage = `✓ Tarea "${completedTask.title}" completada`;
          this.hideSuccessMessageAfterDelay();
        },
        error: (error: Error) => {
          this.handleError('Error al completar tarea: ' + error.message);
        },
      });
  }

  /**
   * Eliminar una tarea
   * 
   * Pide confirmación antes de eliminar (opcional pero recomendado)
   * 
   * @param {ITask} task - Tarea a eliminar
   */
  deleteTask(task: ITask): void {
    const confirmDelete = window.confirm(
      `¿Estás seguro de que quieres eliminar la tarea "${task.title}"?`,
    );

    if (!confirmDelete) {
      return;
    }

    this.deletingTaskId = task.id;

    this.taskService
      .deleteTask(task.id)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          // Remover tarea de la lista
          this.tasks = this.tasks.filter((t) => t.id !== task.id);

          // Recargar filtro
          this.applyFilter(this.activeFilter);

          // Actualizar estadísticas
          this.loadStatistics();

          // Mostrar mensaje de éxito
          this.successMessage = `✓ Tarea eliminada exitosamente`;
          this.hideSuccessMessageAfterDelay();

          this.deletingTaskId = null;
        },
        error: (error: Error) => {
          this.handleError('Error al eliminar tarea: ' + error.message);
          this.deletingTaskId = null;
        },
      });
  }

  /**
   * Aplicar filtro a las tareas
   * 
   * @param {'all' | 'pending' | 'completed'} filter - Filtro a aplicar
   */
  applyFilter(filter: 'all' | 'pending' | 'completed'): void {
    this.activeFilter = filter;

    switch (filter) {
      case 'pending':
        this.filteredTasks = this.tasks.filter((t) => !t.isCompleted);
        break;
      case 'completed':
        this.filteredTasks = this.tasks.filter((t) => t.isCompleted);
        break;
      case 'all':
      default:
        this.filteredTasks = this.tasks;
    }
  }

  /**
   * Obtener el número de tareas en filtro actual
   * 
   * @returns {number} Cantidad de tareas filtradas
   */
  getFilteredTaskCount(): number {
    return this.filteredTasks.length;
  }

  /**
   * Verificar si el formulario es válido
   * 
   * @returns {boolean} true si el formulario es válido
   */
  isFormValid(): boolean {
    return this.taskForm.valid;
  }

  // ==========================================
  // MÉTODOS PRIVADOS
  // ==========================================

  /**
   * Crear formulario reactivo para tareas
   * 
   * Validaciones:
   * - title: Required, min 3 caracteres, max 255
   * - description: Optional, max 2000 caracteres
   * 
   * @returns {FormGroup} Formulario configurado
   */
  private createTaskForm(): FormGroup {
    return this.formBuilder.group({
      title: [
        '',
        [
          Validators.required,
          Validators.minLength(3),
          Validators.maxLength(255),
        ],
      ],
      description: [
        '',
        [
          Validators.maxLength(2000),
        ],
      ],
    });
  }

  /**
   * Manejar errores y mostrar mensaje
   * 
   * @param {string} message - Mensaje de error
   */
  private handleError(message: string): void {
    this.errorMessage = message;
    console.error(message);

    // Limpiar mensaje después de 5 segundos
    setTimeout(() => {
      this.errorMessage = null;
    }, 5000);
  }

  /**
   * Ocultar mensaje de éxito después de un delay
   */
  private hideSuccessMessageAfterDelay(): void {
    setTimeout(() => {
      this.successMessage = null;
    }, 3000);
  }
}
<div class="container">
  <!-- ==========================================
       HEADER
       ========================================== -->
  <div class="header">
    <h1 class="title">📋 Gestión de Tareas</h1>
    <p class="subtitle">Organiza tus tareas de forma simple y efectiva</p>
  </div>

  <!-- ==========================================
       MENSAJES (Error y Éxito)
       ========================================== -->
  <div class="messages">
    <!-- Mensaje de Error -->
    <div *ngIf="errorMessage" class="alert alert-error">
      <span class="icon">⚠️</span>
      <span class="message">{{ errorMessage }}</span>
      <button class="close-btn" (click)="errorMessage = null">✕</button>
    </div>

    <!-- Mensaje de Éxito -->
    <div *ngIf="successMessage" class="alert alert-success">
      <span class="icon">{{ successMessage }}</span>
    </div>
  </div>

  <!-- ==========================================
       ESTADÍSTICAS
       ========================================== -->
  <div class="statistics-section" *ngIf="statistics">
    <div class="stats-container">
      <div class="stat-card">
        <div class="stat-value">{{ statistics.total }}</div>
        <div class="stat-label">Total de Tareas</div>
      </div>

      <div class="stat-card highlight-pending">
        <div class="stat-value">{{ statistics.pending }}</div>
        <div class="stat-label">Pendientes</div>
      </div>

      <div class="stat-card highlight-completed">
        <div class="stat-value">{{ statistics.completed }}</div>
        <div class="stat-label">Completadas</div>
      </div>

      <div class="stat-card highlight-percentage">
        <div class="stat-value">{{ statistics.completionPercentage }}%</div>
        <div class="stat-label">Completamiento</div>
      </div>
    </div>

    <!-- Progress Bar -->
    <div class="progress-bar-container">
      <div class="progress-bar-background">
        <div
          class="progress-bar-fill"
          [style.width.%]="statistics.completionPercentage"
        ></div>
      </div>
    </div>
  </div>

  <!-- ==========================================
       FORMULARIO PARA CREAR TAREAS
       ========================================== -->
  <div class="form-section">
    <h2 class="section-title">➕ Nueva Tarea</h2>

    <form [formGroup]="taskForm" (ngSubmit)="addTask()" class="task-form">
      <!-- Campo: Título -->
      <div class="form-group">
        <label for="taskTitle" class="label">Título *</label>
        <input
          id="taskTitle"
          type="text"
          formControlName="title"
          placeholder="Ej: Estudiar Angular"
          class="input"
          [class.input-error]="
            taskForm.get('title')?.invalid &&
            taskForm.get('title')?.touched
          "
        />
        <div
          class="error-message"
          *ngIf="
            taskForm.get('title')?.invalid &&
            taskForm.get('title')?.touched
          "
        >
          <span *ngIf="taskForm.get('title')?.errors?.['required']">
            El título es obligatorio
          </span>
          <span *ngIf="taskForm.get('title')?.errors?.['minlength']">
            Mínimo 3 caracteres
          </span>
          <span *ngIf="taskForm.get('title')?.errors?.['maxlength']">
            Máximo 255 caracteres
          </span>
        </div>
      </div>

      <!-- Campo: Descripción -->
      <div class="form-group">
        <label for="taskDescription" class="label">Descripción (opcional)</label>
        <textarea
          id="taskDescription"
          formControlName="description"
          placeholder="Describe tu tarea..."
          class="textarea"
          rows="3"
          [class.input-error]="
            taskForm.get('description')?.invalid &&
            taskForm.get('description')?.touched
          "
        ></textarea>
        <div
          class="error-message"
          *ngIf="
            taskForm.get('description')?.invalid &&
            taskForm.get('description')?.touched
          "
        >
          <span *ngIf="taskForm.get('description')?.errors?.['maxlength']">
            Máximo 2000 caracteres
          </span>
        </div>
      </div>

      <!-- Botón Enviar -->
      <button
        type="submit"
        [disabled]="!isFormValid() || isCreatingTask"
        class="btn btn-primary"
      >
        <span *ngIf="!isCreatingTask">Crear Tarea</span>
        <span *ngIf="isCreatingTask">⏳ Creando...</span>
      </button>
    </form>
  </div>

  <!-- ==========================================
       FILTROS (TABS)
       ========================================== -->
  <div class="filters-section">
    <div class="filter-tabs">
      <button
        class="filter-tab"
        [class.active]="activeFilter === 'all'"
        (click)="applyFilter('all'); loadTasks()"
      >
        📌 Todas ({{ tasks.length }})
      </button>
      <button
        class="filter-tab"
        [class.active]="activeFilter === 'pending'"
        (click)="applyFilter('pending'); loadTasks()"
      >
        ⏳ Pendientes ({{ statistics?.pending || 0 }})
      </button>
      <button
        class="filter-tab"
        [class.active]="activeFilter === 'completed'"
        (click)="applyFilter('completed'); loadTasks()"
      >
        ✅ Completadas ({{ statistics?.completed || 0 }})
      </button>
    </div>
  </div>

  <!-- ==========================================
       LISTA DE TAREAS
       ========================================== -->
  <div class="tasks-section">
    <!-- Loading State -->
    <div *ngIf="isLoadingTasks" class="loading-state">
      <div class="spinner"></div>
      <p>Cargando tareas...</p>
    </div>

    <!-- Empty State -->
    <div *ngIf="!isLoadingTasks && filteredTasks.length === 0" class="empty-state">
      <div class="empty-icon">📭</div>
      <p class="empty-message">
        <span *ngIf="activeFilter === 'all'">
          No hay tareas aún. ¡Crea una nueva!
        </span>
        <span *ngIf="activeFilter === 'pending'">
          No hay tareas pendientes. ¡Bien hecho!
        </span>
        <span *ngIf="activeFilter === 'completed'">
          No has completado tareas aún.
        </span>
      </p>
    </div>

    <!-- Tasks List -->
    <div *ngIf="!isLoadingTasks && filteredTasks.length > 0" class="tasks-list">
      <div *ngFor="let task of filteredTasks" class="task-card" [class.completed]="task.isCompleted">
        <!-- Checkbox para marcar completado -->
        <div class="task-checkbox">
          <input
            type="checkbox"
            [checked]="task.isCompleted"
            [id]="'task-' + task.id"
            (change)="completeTask(task)"
            class="checkbox-input"
          />
          <label [for]="'task-' + task.id" class="checkbox-label"></label>
        </div>

        <!-- Contenido de la tarea -->
        <div class="task-content">
          <!-- Título -->
          <h3 class="task-title" [class.strike-through]="task.isCompleted">
            {{ task.title }}
          </h3>

          <!-- Descripción -->
          <p *ngIf="task.description" class="task-description">
            {{ task.description }}
          </p>

          <!-- Metadata -->
          <div class="task-metadata">
            <span class="task-date">
              📅 {{ task.createdAt | date: 'short' }}
            </span>
            <span *ngIf="task.isCompleted" class="task-status status-completed">
              ✅ Completada
            </span>
            <span *ngIf="!task.isCompleted" class="task-status status-pending">
              ⏳ Pendiente
            </span>
          </div>
        </div>

        <!-- Acciones -->
        <div class="task-actions">
          <!-- Botón Completar -->
          <button
            *ngIf="!task.isCompleted"
            class="btn-action btn-complete"
            (click)="completeTask(task)"
            title="Marcar como completada"
          >
            ✓
          </button>

          <!-- Botón Eliminar -->
          <button
            class="btn-action btn-delete"
            (click)="deleteTask(task)"
            [disabled]="deletingTaskId === task.id"
            title="Eliminar tarea"
          >
            <span *ngIf="deletingTaskId !== task.id">🗑️</span>
            <span *ngIf="deletingTaskId === task.id">⏳</span>
          </button>
        </div>
      </div>
    </div>
  </div>
</div>

<!-- 
  NOTAS SOBRE LA ESTRUCTURA:

  1. COMPONENTES VISUALES:
     - Header: Título e introducción
     - Estadísticas: Tarjetas con conteos y porcentaje
     - Formulario: Inputs validados reactivamente
     - Filtros: Tabs para cambiar vista
     - Lista: Cards de tareas con acciones

  2. RESPONSIVE DESIGN:
     - Grid en estadísticas (se adapta a mobile)
     - Botones big enough para touch
     - Formulario full-width en mobile

  3. VALIDACIÓN:
     - Mensajes de error bajo cada campo
     - Botón deshabilitado si formulario es inválido
     - Indicadores visuales de estado

  4. UX:
     - Estados de carga (spinner)
     - Este vacío (cuando no hay tareas)
     - Mensajes de confirmación
     - Loading en botones de acción

  5. ACCESIBILIDAD:
     - Labels asociados con inputs (for/id)
     - Titles en botones
     - Contraste de colores
     - Estructura semántica correcta
-->
